require_once dirname(__DIR__) . '/_common.php';$id=isset($_GET['id'])?(int)$_GET['id']:(isset($_POST['album_id'])?(int)$_POST['album_id']:0);$stmt=$pdo->prepare('SELECT * FROM galeri_album WHERE id=?');$stmt->execute([$id]);$album=$stmt->fetch();if(!$album){osis_set_flash('error','Album tidak ditemukan.');osis_redirect('admin/galeri/index.php');}$pageTitle='Unggah foto';$error='';
if(osis_admin_is_post()){osis_verify_csrf();$caption=osis_post_string('keterangan',220);$files=isset($_FILES['foto'])?$_FILES['foto']:null;$saved=[];$count=0;if(!$files||empty($files['name'])||!is_array($files['name'])){$error='Pilih setidaknya satu foto.';}else{try{$pdo->beginTransaction();foreach($files['name'] as $i=>$filename){if((int)$files['error'][$i]===UPLOAD_ERR_NO_FILE)continue;$one=['name'=>$filename,'type'=>$files['type'][$i],'tmp_name'=>$files['tmp_name'][$i],'error'=>$files['error'][$i],'size'=>$files['size'][$i]];$path=osis_store_uploaded_image($one,'galeri');if($path){$saved[]=$path;$stmt=$pdo->prepare('INSERT INTO galeri_foto(album_id,file,keterangan) VALUES(?,?,?)');$stmt->execute([$id,$path,$caption?:null]);$count++;}}if($count===0){throw new RuntimeException('Pilih setidaknya satu foto.');}$pdo->commit();osis_log_activity('Mengunggah '.$count.' foto ke album: '.$album['judul']);osis_set_flash('success',$count.' foto berhasil diunggah.');osis_redirect('admin/galeri/foto-upload.php?id='.$id);}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();foreach($saved as $path)osis_delete_uploaded_file($path);$error=osis_admin_handle_error($exception);}}}
$stmt=$pdo->prepare('SELECT * FROM galeri_foto WHERE album_id=? ORDER BY created_at DESC,id DESC');$stmt->execute([$id]);$photos=$stmt->fetchAll();osis_admin_page_start($pageTitle);
?>
<div class="admin-form-wrap wide-form"><a class="back-link" href="<?=osis_e(osis_url('admin/galeri/index.php'))?>">← Galeri</a><div class="admin-panel form-panel"><div class="album-upload-heading"><div><span class="eyebrow">ALBUM FOTO</span><h2><?=osis_e($album['judul'])?></h2><p><?=osis_e(osis_format_date($album['tanggal']))?> · <?=count($photos)?> foto tersimpan</p></div><a class="button button-outline" href="<?=osis_e(osis_url('admin/galeri/album-edit.php?id='.$id))?>">Edit album</a></div><?php if($error):?><div class="alert alert-error"><?=osis_e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" data-validate-form><?=osis_csrf_input()?><input type="hidden" name="album_id" value="<?=$id?>"><label for="foto">Pilih foto <span class="optional">JPG, PNG, WEBP · maksimal 5 MB per foto</span></label><input id="foto" name="foto[]" type="file" accept="image/jpeg,image/png,image/webp" multiple required><label for="keterangan">Keterangan umum <span class="optional">(opsional, dipakai untuk setiap foto yang dipilih)</span></label><input id="keterangan" name="keterangan" maxlength="220" placeholder="Contoh: Keseruan hari pertama"><div class="form-actions"><a class="button button-outline" href="<?=osis_e(osis_url('admin/galeri/index.php'))?>">Selesai</a><button class="button button-primary" type="submit">Unggah foto <span>↗</span></button></div></form></div><?php if($photos):?><div class="admin-photo-grid"><?php foreach($photos as $photo):?><article class="admin-photo-card"><img src="<?=osis_e(osis_image_url($photo['file']))?>" alt="<?=osis_e($photo['keterangan']?:$album['judul'])?>"><div><p><?=osis_e($photo['keterangan']?:'Tanpa keterangan')?></p><form method="post" action="<?=osis_e(osis_url('admin/galeri/foto-hapus.php'))?>" data-confirm="Hapus foto ini?"><?=osis_csrf_input()?><input type="hidden" name="id" value="<?=(int)$photo['id']?>"><input type="hidden" name="album_id" value="<?=$id?>"><button class="table-action danger-text" type="submit">Hapus foto</button></form></div></article><?php endforeach;?></div><?php endif;?></div>
